css:
.rm-t-timeline{padding:0 0 48px;color:#25303f;background:#ffffff;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;}
.rm-t-timeline .rm-head{padding:0 56px 24px;background:#f8fafc;border-bottom:1px solid #e2e8f0;}
.rm-t-timeline .rm-head::before{content:"";display:block;height:5px;margin:0 -56px 30px;background:linear-gradient(90deg,#2563eb 0%,#7db0f7 60%,#dbeafe 100%);}
.rm-t-timeline .rm-name{font-size:36px;font-weight:700;letter-spacing:.02em;line-height:1.15;color:#0f172a;}
.rm-t-timeline .rm-role{margin:8px 0 0;font-size:12.5px;letter-spacing:.18em;color:#2563eb;}
.rm-t-timeline .rm-contact{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px 18px;margin-top:18px;}
.rm-t-timeline .rm-k{display:inline-block;padding:1px 7px;border-radius:4px;background:#e8f0fe;color:#3b63a8;font-size:9.5px;letter-spacing:.04em;}
.rm-t-timeline .rm-v{font-size:11.5px;color:#334155;}
.rm-t-timeline .rm-body{padding:0 56px;}
.rm-t-timeline .rm-sec{margin-top:24px;}
.rm-t-timeline .rm-sec-h{margin:0 0 12px;padding-bottom:6px;border-bottom:1px dashed #c7d7ee;gap:0;}
.rm-t-timeline .rm-sec-t{font-size:12px;font-weight:700;letter-spacing:.22em;color:#1d4ed8;}
.rm-t-timeline .rm-items{position:relative;}
.rm-t-timeline .rm-items::before{content:"";position:absolute;left:110px;top:12px;bottom:8px;width:1px;background:#d7e2f3;}
.rm-t-timeline .rm-item{position:relative;padding-left:128px;margin-bottom:16px;}
.rm-t-timeline .rm-item::before{content:"";position:absolute;left:104px;top:6px;width:8px;height:8px;border-radius:50%;background:#ffffff;border:2px solid #2563eb;box-shadow:0 0 0 3px #e8f0fe;z-index:1;}
.rm-t-timeline .rm-item::after{display:none;}
.rm-t-timeline .rm-item:last-child::after{display:none;}
.rm-t-timeline .rm-row{display:block;}
.rm-t-timeline .rm-date{position:absolute;left:0;top:2px;width:86px;text-align:right;font-size:10.5px;letter-spacing:.02em;color:#64748b;line-height:1.5;}
.rm-t-timeline .rm-item-main{display:block;}
.rm-t-timeline .rm-item-t{display:block;font-size:14px;font-weight:600;color:#0f172a;}
.rm-t-timeline .rm-item-role{display:inline-block;margin-top:3px;font-size:11.5px;color:#5b6b82;}
.rm-t-timeline .rm-item-sub{font-size:11.5px;color:#64748b;}
.rm-t-timeline .rm-edu-courses{font-size:11px;line-height:1.5;color:#64748b;}
.rm-t-timeline .rm-bullets{margin-top:5px;padding-left:14px;}
.rm-t-timeline .rm-bullets li{margin:2px 0;font-size:12.5px;color:#3c4a5e;}
.rm-t-timeline .rm-bullets li::marker{color:#94b3e6;}
.rm-t-timeline .rm-summary{font-size:13px;line-height:1.75;color:#3c4a5e;}
.rm-t-timeline .rm-tag{border:1px solid #d3e0f5;background:#f1f6fe;color:#2a4d86;border-radius:4px;font-size:11px;}
.rm-t-timeline .rm-skill-row{grid-template-columns:88px minmax(0,1fr);gap:10px;margin-bottom:7px;}
.rm-t-timeline .rm-skill-k{font-size:11px;font-weight:600;letter-spacing:.06em;color:#1d4ed8;}
.rm-t-timeline .rm-award-row{margin-bottom:6px;}
.rm-t-timeline .rm-award-t{font-size:12.5px;color:#0f172a;}
.rm-t-timeline .rm-award-desc{font-size:11px;color:#64748b;}
.rm-t-timeline .rm-sec-campus .rm-item{padding-left:128px;}
.rm-t-timeline .rm-sec-hobbies .rm-tags{padding-left:0;}
